@js:
let start = key.slice(0,1);
let type;
let f = true;

if(cache.get("bilibili_search_2")=="1"){
	cache.delete("bilibili_search_2");
	f = false;
	start = String(cache.get("bilibili_search"));
	key = start + key;
}

switch(start){
	case "@":
	    type = "bili_user";
	    break;
	case "#":
	case "＃":
	    type = "article"
	    break;
	case "%":
	    type = "video"
	    break
	case "&":
	    type = "live"
