jsLib:
var XY_API_ROOT = "https://full.hnxianxin.cn/qd/";
var XY_COVER_ROOT = "https://bookcover.yuewen.com/qdbimg/349573/";

var XY_TEXT_SITES = { 11: 1, 12: 1, 4: 1 };
var XY_QUERY_NAMES = {
  categoryid: "category_id",
  subcategoryid: "subcategory_id",
  classid: "class_id",
  actionstatus: "action_status",
  wordscount: "words_count",
  paidmode: "paid_mode",
  tagtype: "tag_type",
  great: "great",
  endure: "endure",
  tagid: "tag_ids",
};
var XY_FILTER_TITLES = {
  actionstatus: "连载状态",
  wordscount: "字数范围",
  paidmode: "付费模式",
  tagtype: "标签匹配",
  classid: "标签筛选",
  great: "精品筛选",
  endure: "耐看筛选",
};

function xyBridge(ctx) {
  if (ctx && ctx.java) return ctx.java;
  if (typeof java !== "undefined") return java;
  return null;
}

function xySource(ctx) {
  if (ctx && ctx.source) return ctx.source;
  if (typeof source !== "undefined") return source;
  return null;
}

function xyState(ctx) {
  var holder = xySource(ctx);
  var state = {};
  try {
    state = JSON.parse(holder.getVariable() || "{}");
  } catch (error) {
    state = {};
  }
  if (!state || typeof state !== "object") state = {};
  if (state.xySite === "男站") state.xySite = "男生";
  if (state.xySite === "女站") state.xySite = "女生";
  if (!state.xySite || !XY_TEXT_SITES[String(xySiteIdByName(state.xySite))])
    state.xySite = "男生";
  if (!state.xyOrderName || state.xyOrderName === "默认榜单")
    state.xyOrderName = "人气最高";
  if (!state.xyCategoryName) state.xyCategoryName = "全部";
  if (!state.xyActionStatusName) state.xyActionStatusName = "不限";
  if (!state.xyWordsCountName) state.xyWordsCountName = "不限";
  if (!state.xyPaidModeName) state.xyPaidModeName = "不限";
  if (!state.xyTagTypeName) state.xyTagTypeName = "包含任意已选标签";
  if (!state.xyGreatName) state.xyGreatName = "不限";
  if (!state.xyEndureName) state.xyEndureName = "不限";
  if (!state.xyTagValue) state.xyTagValue = "";
  if (state.xyShowPara !== false) state.xyShowPara = true;
  if (state.xyShowChapter !== false) state.xyShowChapter = true;
  if (state.xyLargeBubble !== false) state.xyLargeBubble = true;
  if (state.xyFullComment !== true) state.xyFullComment = false;
  if (state.xyCustomMode !== true) state.xyCustomMode = false;
  state.xyYwkey = String(state.xyYwkey || "");
  state.xyYwguid = String(state.xyYwguid || "");
  state.xyUserToken = String(state.xyUserToken || "");
  state.xyAndroidId = String(state.xyAndroidId || "");
  state.xyUserName = String(state.xyUserName || "");
  state.xyUserLevel = String(state.xyUserLevel || "");
  return state;
}

function xySiteIdByName(name) {
  if (name === "女生") return 12;
  if (name === "出版") return 4;
  return 11;
}

function xyGet(ctx, key, fallback) {
  var state = xyState(ctx);
  return Object.prototype.hasOwnProperty.call(state, key)
    ? state[key]
    : fallback;
}

function xyAjax(ctx, url) {
  var bridge = xyBridge(ctx);
  if (!bridge) throw new Error("java context is unavailable");
  return bridge.ajax(url);
}

function xyJson(ctx, url) {
  return JSON.parse(xyAjax(ctx, url));
}

function xySearchUrl(ctx, keyword, page) {
  var value = String(keyword || "").replace(/^\s+|\s+$/g, "");
  var pageNumber = Math.max(1, parseInt(String(page || "1"), 10) || 1);
  return (
    XY_API_ROOT +
    "search.php?keyword=" +
    encodeURIComponent(value) +
    "&site=1&page=" +
    pageNumber +
    "&page_size=20"
  );
}

function xyDetailUrl(ctx, id) {
  return (
    XY_API_ROOT + "detail.php?bookId=" + encodeURIComponent(String(id || ""))
  );
}

function xyCatalogUrl(ctx, id) {
  return (
    XY_API_ROOT + "catalog.php?bookId=" + encodeURIComponent(String(id || ""))
  );
}

function xyCoverUrl(ctx, id) {
  return XY_COVER_ROOT + encodeURIComponent(String(id || "")) + "/180";
}

function xyNormalizeBase64(value) {
  var encoded = String(value || "").replace(/\s+/g, "");
  encoded = encoded.replace(/-/g, "+").replace(/_/g, "/");
  while (encoded.length % 4) encoded += "=";
  return encoded;
}

function xyDecodeChapter(ctx, value) {
  var text = String(value || "");
  try {
    text = decodeURIComponent(text);
  } catch (error) {}
  if (text.charAt(0) === "{") return JSON.parse(text);
  var match = text.match(/base64,([A-Za-z0-9+\/=_%-]+)/i);
  var encoded = match ? match[1] : text;
  if (!encoded) throw new Error("章节地址无效");
  var separator = encoded.indexOf(",");
  if (separator >= 0) encoded = encoded.substring(0, separator);
  var json = xyBridge(ctx).base64Decode(xyNormalizeBase64(encoded));
  var data = JSON.parse(json);
  if (
    !data ||
    !data.bookId ||
    data.chapterId === undefined ||
    data.chapterId === null ||
    data.chapterId === ""
  ) {
    throw new Error("章节信息无效");
  }
  if (
    !Object.prototype.hasOwnProperty.call(data, "time") ||
    !/^\d+$/.test(String(data.time))
  ) {
    throw new Error("章节时间戳无效，请刷新目录");
  }
  if (String(data.time) === "0") {
    throw new Error("章节时间戳无效，请刷新目录");
  }
  return data;
}

function xyChapterPayload(ctx, value) {
  return String(xyBridge(ctx).hexDecodeToString(String(value || "")) || "");
}

function xyCustomHeaders(ctx) {
  var state = xyState(ctx);
  if (!state.xyCustomMode || !state.xyYwkey || !state.xyYwguid) return null;
  return { Ywkey: String(state.xyYwkey), Ywguid: String(state.xyYwguid) };
}
function xyUserAndroidId(ctx, state) {
  var value = String(state.xyAndroidId || "").replace(/^\s+|\s+$/g, "");
  if (value) return value;
  try { if (xyBridge(ctx).androidId) value = String(xyBridge(ctx).androidId() || ""); } catch (error) {}
  if (!value) {
    var chars = "0123456789abcdef";
    for (var index = 0; index < 16; index++) value += chars.charAt(Math.floor(Math.random() * 16));
  }
  return value.toUpperCase();
}
function xyEnsureUser(ctx) {
  var state = xyState(ctx);
  if (state.xyCustomMode || state.xyUserToken) return state;
  var androidId = xyUserAndroidId(ctx, state);
  var options = {method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify({android_id:androidId})};
  var response = JSON.parse(xyAjax(ctx, XY_API_ROOT + "user_api.php?action=guest," + JSON.stringify(options)));
  if (response.error) throw new Error(response.error);
  var user = response.user || {};
  state.xyAndroidId = androidId;
  state.xyUserToken = String(response.token || "");
  state.xyUserName = String(user.username || "");
  state.xyUserLevel = String(user.level || "guest");
  var holder = xySource(ctx);
  if (holder && holder.setVariable) holder.setVariable(JSON.stringify(state));
  return state;
}
function xyUserHeaders(ctx) {
  var custom = xyCustomHeaders(ctx);
  if (custom) return custom;
  var state = xyEnsureUser(ctx);
  if (!state.xyUserToken) return null;
  return {"X-Sec-Token":String(state.xyUserToken),"X-Android-Id":String(state.xyAndroidId || "")};
}
function xyContentUrl(ctx, value) {
  var data = xyDecodeChapter(ctx, value);
  var vip = Number(data.v !== undefined ? data.v : data.vip) ? 1 : 0;
  var epub = Number(data.epub) ? 1 : 0;
  var url = XY_API_ROOT + "content.php?bookId=" + encodeURIComponent(String(data.bookId)) + "&chapterId=" + encodeURIComponent(String(data.chapterId)) + "&t=" + encodeURIComponent(String(data.time)) + "&epub=" + epub + "&v=" + vip;
  var headers = xyUserHeaders(ctx);
  return headers ? url + "," + JSON.stringify({headers:headers}) : url;
}

function xyQuery(ctx, url, name) {
  var match = String(url || "").match(
    new RegExp("[?&]" + name + "=([^&]+)", "i"),
  );
  if (!match) return "";
  try {
    return decodeURIComponent(match[1]);
  } catch (error) {
    return match[1];
  }
}

function xyReviewUrl(ctx, value) {
  var bookId = xyQuery(ctx, value, "bookId");
  var chapterId = xyQuery(ctx, value, "chapterId");
  var page = xyQuery(ctx, value, "page") || "1";
  return (
    XY_API_ROOT +
    "review.php?bookId=" +
    encodeURIComponent(bookId) +
    "&chapterId=" +
    encodeURIComponent(chapterId) +
    "&page=" +
    encodeURIComponent(page)
  );
}

function xyCleanText(value) {
  var images = [];
  var text = String(value || "").replace(/<img\b[^>]*>/gi, function (tag) {
    images.push(tag);
    return "\n@@XY_IMG_" + (images.length - 1) + "@@\n";
  });
  text = text
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/p>/gi, "\n")
    .replace(/<[^>]+>/g, "")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/\r\n?/g, "\n");
  return text.replace(/@@XY_IMG_(\d+)@@/g, function (all, index) {
    return images[Number(index)] || "";
  });
}

function xyH5Url(bookId, chapterId, paragraphId) {
  var url =
    XY_API_ROOT +
    "index.html?bookId=" +
    encodeURIComponent(String(bookId)) +
    "&chapterId=" +
    encodeURIComponent(String(chapterId));
  if (paragraphId !== undefined && paragraphId !== null && paragraphId !== "") {
    url += "&paragraphIndex=" + encodeURIComponent(String(paragraphId));
  }
  return url;
}

function xyCommentBrowserConfig(ctx) {
  var fullScreen = xyGet(ctx, "xyFullComment", false);
  var config = {
    state: fullScreen ? 3 : 4,
    isHideable: true,
    skipCollapsed: true,
    hardwareAccelerated: true,
    widthPercentage: 1,
    maxWidth: -1,
    expandedCornersRadius: fullScreen ? 0 : 14,
    dismissOnTouchOutside: true,
    isGestureInsetBottomIgnored: true,
    webViewInitialScale: 100,
  };
  if (fullScreen) {
    config.dialogHeight = -1;
    config.setFitToContents = false;
    config.setExpandedOffset = 0;
  } else {
    config.heightPercentage = 0.7;
  }
  return config;
}

function xyShowComment(bridge, url, title) {
  if (!bridge || !url) return;
  if (bridge.showBrowser) {
    bridge.showBrowser(
      String(url),
      null,
      null,
      JSON.stringify(xyCommentBrowserConfig(this)),
    );
    return;
  }
  bridge.startBrowser(String(url), String(title || "评论"));
}

function xyCommentCounts(ctx, bookId, chapterId) {
  var map = {};
  var chapterCount = 0;
  try {
    var response = xyJson(
      ctx,
      XY_API_ROOT +
        "review.php?bookId=" +
        encodeURIComponent(String(bookId)) +
        "&chapterId=" +
        encodeURIComponent(String(chapterId)),
    );
    var root = response.data || response.Data || {};
    var list = (root.Getparagraphscommentcounts || {}).DataList || [];
    for (var index = 0; index < list.length; index++) {
      var item = list[index];
      var paragraph = Number(item.ParagraphId);
      var count = Number(item.CommentCount);
      if (paragraph === -1) {
        chapterCount = count;
      } else if (paragraph >= 0 && count > 0) {
        map[String(paragraph)] = {
          count: count,
          hot: Number(item.HasHotComment || item.hasHotComment || 0) === 1,
        };
      }
    }
  } catch (error) {
    try {
      xyBridge(ctx).log("评论数量获取失败：" + error);
    } catch (ignored) {}
  }
  return { map: map, chapter: chapterCount };
}

function xyCommentBubble(ctx, count, bookId, chapterId, paragraphId, hot) {
  var bridge = xyBridge(ctx);
  if (!bridge || !bridge.base64Encode) return "";
  var display = Number(count) > 99 ? "99+" : String(Number(count) || 0);
  var font = "system-ui,-apple-system,Arial,sans-serif";
  var svg =
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="5 14 45 36" width="180" height="144">' +
    '<path d="M44 48 Q48 48 48 44 L48 20 Q48 16 44 16 L20 16 Q16 16 16 20 L16 24 S16 28 10 30 Q6 32 10 34 Q16 36 16 38 L16 44 Q16 48 20 48 Z" fill="none" stroke="#666666" stroke-width="0.7"/>' +
    '<text x="32" y="36.5" text-anchor="middle" font-family="' +
    font +
    '" font-weight="600" font-size="11" fill="#666666">' +
    display +
    "</text></svg>";
  var options = {
    style: xyGet(ctx, "xyLargeBubble", true) ? "TEXT" : "text",
    type: "xy",
    status: hot ? "emphasis" : "normal",
    click:
      "xyShowComment.call(this, java," +
      JSON.stringify(xyH5Url(bookId, chapterId, paragraphId)) +
      ',"段评")',
    marker: "xyComment:" + bookId + ":" + chapterId + ":" + paragraphId,
  };
  return (
    '<img src="data:' +
    "image/svg+xml;base64," +
    bridge.base64Encode(svg) +
    "," +
    JSON.stringify(options) +
    '">'
  );
}

function xyXmlEscape(text) {
  return String(text || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function xyCommentCard(ctx, count, bookId, chapterId) {
  var bridge = xyBridge(ctx);
  if (!bridge || !bridge.base64Encode || Number(count) <= 0) return "";
  var width = 1080,
    height = 150,
    left = 60,
    right = 60;
  var svg =
    '<svg width="' +
    width +
    '" height="' +
    height +
    '" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">' +
    '<rect x="2" y="2" width="' +
    (width - 4) +
    '" height="' +
    (height - 4) +
    '" fill="rgba(255,255,255,0.25)" rx="59" stroke="#888" stroke-width="1"/>' +
    '<text x="' +
    left +
    '" y="88" font-size="46" font-family="Segoe UI,Arial,sans-serif" fill="#333333">本章说</text>' +
    '<text x="' +
    (width - right) +
    '" y="86" font-size="38" text-anchor="end" font-family="Segoe UI,Arial,sans-serif" fill="#666666">' +
    xyXmlEscape(Number(count) + "条评论 ❯") +
    "</text>" +
    "</svg>";
  var options = {
    style: "FULL",
    click:
      "xyShowComment.call(this, java," +
      JSON.stringify(xyH5Url(bookId, chapterId)) +
      ',"本章评论")',
    marker: "xyCommentTail:" + bookId + ":" + chapterId,
  };
  return (
    '<img src="data:' +
    "image/svg+xml;base64," +
    bridge.base64Encode(svg) +
    "," +
    JSON.stringify(options) +
    '">'
  );
}

function xyFormatContent(ctx, body, baseUrl) {
  var response;
  try {
    response = JSON.parse(body);
  } catch (error) {
    throw new Error("正文响应不是JSON：" + String(body).substring(0, 120));
  }
  if (response.error) throw new Error(response.error);
  if (response.detail) throw new Error(response.detail);
  if (
    response.code !== undefined &&
    Number(response.code) !== 0 &&
    response.msg
  )
    throw new Error(response.msg);

  var content =
    response.content ||
    response.Content ||
    (response.Data && response.Data.Content) ||
    "";
  if (!content) throw new Error("正文内容为空");

  var bookId = xyQuery(ctx, baseUrl, "bookId");
  var chapterId = xyQuery(ctx, baseUrl, "chapterId");
  var state = xyState(ctx);
  var counts =
    state.xyShowPara || state.xyShowChapter
      ? xyCommentCounts(ctx, bookId, chapterId)
      : { map: {}, chapter: 0 };
  var lines = xyCleanText(content).split("\n");
  var output = [];
  var paragraphIndex = 1;

  for (var index = 0; index < lines.length; index++) {
    var line = lines[index].replace(/^\s+|\s+$/g, "");
    if (!line) continue;
    if (/<img\b/i.test(line)) {
      output.push(line);
      continue;
    }
    var idea = counts.map[String(paragraphIndex)];
    if (
      state.xyShowPara &&
      idea &&
      idea.count > 0 &&
      line.indexOf(
        "xyComment:" + bookId + ":" + chapterId + ":" + paragraphIndex,
      ) < 0
    ) {
      line +=
        " " +
        xyCommentBubble(
          ctx,
          idea.count,
          bookId,
          chapterId,
          paragraphIndex,
          idea.hot,
        );
    }
    output.push(line);
    paragraphIndex++;
  }

  if (state.xyShowChapter) {
    var card = xyCommentCard(ctx, counts.chapter, bookId, chapterId);
    if (card) output.push("", card);
  }
  return output.join("\n");
}
function xySearchItems(ctx, body) {
  var response = JSON.parse(body);
  var cards = (response.Data || {}).CardList || [];
  var output = [];
  for (var cardIndex = 0; cardIndex < cards.length; cardIndex++) {
    var rows = cards[cardIndex].Body || [];
    for (var rowIndex = 0; rowIndex < rows.length; rowIndex++) {
      var item = rows[rowIndex].ItemData;
      if (item && Number(item.BookId) > 0 && Number(item.BookType) === 1) {
        output.push(JSON.stringify(item));
      }
    }
  }
  return output;
}

function xyExploreItems(ctx, body) {
  var list = (JSON.parse(body).Data || {}).Books || [];
  var output = [];
  for (var index = 0; index < list.length; index++)
    output.push(JSON.stringify(list[index]));
  return output;
}

function xyKind(data) {
  var values = [
    data.CategoryName,
    data.SubCategoryName,
    data.ActionStatusString,
    data.BookStatus,
    data.WordsCount,
  ];
  var tags = data.BookTags || [];
  for (var tagIndex = 0; tagIndex < tags.length && tagIndex < 4; tagIndex++)
    values.push(tags[tagIndex]);
  var output = [];
  for (var index = 0; index < values.length; index++) {
    var value = String(values[index] || "").replace(/^\s+|\s+$/g, "");
    if (value && value !== "0") output.push(value);
  }
  return output.join("·");
}

function xyFallbackConfig() {
  return {
    sites: [
      { Id: 11, Name: "男生" },
      { Id: 12, Name: "女生" },
      { Id: 4, Name: "出版" },
    ],
    orders: [{ Id: 11, Name: "人气最高" }],
    lines: [],
    filterOne: [],
    valid: false,
  };
}

function xyConfigLine(lines, tag) {
  for (var index = 0; index < (lines || []).length; index++) {
    if (lines[index].Tag === tag) return lines[index];
  }
  return {};
}

function xyOptions(line) {
  return line && line.FilterUnions ? line.FilterUnions : [];
}

function xyNames(options) {
  var output = [];
  for (var index = 0; index < (options || []).length; index++)
    output.push(String(options[index].Name));
  return output;
}

function xySelected(options, name) {
  for (var index = 0; index < (options || []).length; index++) {
    if (String(options[index].Name) === String(name)) return options[index];
  }
  return options && options.length ? options[0] : null;
}

function xyOptional(options, name) {
  if (!name) return null;
  for (var index = 0; index < (options || []).length; index++) {
    if (String(options[index].Name) === String(name)) return options[index];
  }
  return null;
}

function xyOptionId(options, name, fallback) {
  var selected = xySelected(options, name);
  return selected && selected.Id !== undefined ? selected.Id : fallback;
}

function xyLoadConfig(ctx, state) {
  var config = xyFallbackConfig();
  var siteId = xyOptionId(config.sites, state.xySite, 11);
  try {
    var response = xyJson(
      ctx,
      XY_API_ROOT + "ranking.php?action=config&site_id=" + siteId,
    );
    var data = response.Data || response.data || {};
    var resultCode =
      response.Result !== undefined
        ? Number(response.Result)
        : Number(response.result || 0);
    if (resultCode === 0 && data) {
      var sites = (data.SiteList || []).filter(function (item) {
        return XY_TEXT_SITES[String(Number(item.Id))] === 1;
      });
      if (sites.length) config.sites = sites;
      config.orders = data.Orders || [];
      config.lines = data.FiltrLines || [];
      config.filterOne = data.FilterOne || [];
      config.valid = true;
    }
  } catch (error) {
    try {
      xyBridge(ctx).log("发现配置加载失败：" + error);
    } catch (ignored) {}
  }
  if (!config.orders.length) config.orders = xyFallbackConfig().orders;
  return config;
}

function xySelectAction(key, title, clearKeys, syncInfo) {
  var clear = "";
  if (clearKeys && clearKeys.length) {
    for (var index = 0; index < clearKeys.length; index++) {
