      for (var j = 0; j < episodes.length; j++) {
        if (!episodes[j]) continue;
        var parts = episodes[j].split('$');
        // 核心修复点：无视垃圾站的数据缺失，强吃裸链
        if (parts.length > 1) {
          list.push({ name: lineName + ' - ' + parts[0], url: parts[1] });
        } else {
          var epName = episodes.length > 1 ? ('第' + (j+1) + '集') : '播放';
          list.push({ name: lineName + ' - ' + epName, url: parts[0] });
        }
      }
    }
  } catch(e) {}
}
list;

