function fetchMoreComments(t) {
    return new Promise((resolve) => {
        setTimeout(() => {
            let type = document.querySelector(".tab-btn.active").textContent;
            if(type == "热门评论"){
                hotJson.pagination_str = JSON.stringify({"offset":offset});
                currentUrl = "https://api.bilibili.com/x/v2/reply/wbi/main?"+getWbiEnc(hotJson);
            }else if(type == "最新评论"){
                newJson.pagination_str = JSON.stringify({"offset":offset});
                currentUrl = "https://api.bilibili.com/x/v2/reply/wbi/main?"+getWbiEnc(newJson)
            }

            let htmlString = "";
            if(t){
                replyapi = replyapi.replace(/pn=\\d+/,'pn='+replyPage);
                let replyJson = getJson(replyapi,2);
                htmlString = createHtml(replyJson.list,"comment");
            }else{
                htmlString = createCommentHtml(getJson(currentUrl));
            }

            const container = t?document.querySelector(".reply-content"): document.querySelector('.comments-container');
            const loader = container.querySelector('.loading-more');
            if (loader) {
                loader.insertAdjacentHTML('beforebegin', htmlString);
             } else {
                 container.insertAdjacentHTML('beforeend', htmlString);
             }
             t?null:openReply()
            resolve();
        }, 1000);
    });
}

